.solar-heading{padding:30px 0}.solar-heading h1{font-size:clamp(42px,6vw,76px);line-height:1.12;letter-spacing:-.05em;margin:20px 0}.solar-heading h1 span{color:#527cac}.solar-heading>p:last-child{font-size:15px;color:var(--muted)}.solar-toolbar{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin:8px 0 20px}.solar-toolbar .button{font-size:12px;padding:11px 17px}.solar-toolbar label{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--muted)}.solar-toolbar select{border:1px solid var(--border);border-radius:9px;background:#fff;padding:8px;color:var(--ink)}.solar-layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:20px}.solar-stage{position:relative;height:580px;border-radius:24px;overflow:hidden;background:#edf1f6;border:1px solid #e1e6ee}.solar-canvas,.solar-canvas :deep(canvas){width:100%;height:100%;display:block}.solar-canvas :deep(.solar-label){position:absolute;top:0;left:0;font-size:10px;background:#ffffffe0;padding:3px 6px;border-radius:5px;color:#47576c;white-space:nowrap}.solar-stage-note{position:absolute;bottom:15px;left:18px;font-size:11px;color:#596b80;background:#ffffffc0;border-radius:99px;padding:8px 13px;pointer-events:none}.solar-error{position:absolute;inset:0;display:grid;place-items:center;padding:40px;text-align:center;line-height:2;color:#52657b}.solar-information{border:1px solid var(--border);border-radius:24px;background:#fff;padding:24px}.solar-information h2{font-size:35px;letter-spacing:-.04em;margin:15px 0}.solar-information p{font-size:13px;line-height:1.9;color:var(--muted)}.solar-information .solar-type{font-size:11px;color:#52657b}.solar-information a,.solar-information .text-button{display:block;color:#0066cc;font-size:12px;margin:18px 0}.solar-information small{display:block;font-size:11px;line-height:1.9;color:var(--muted);border-top:1px solid var(--border);padding-top:18px}.solar-planet-preview{height:140px;display:grid;place-items:center;position:relative}.solar-planet-preview>span{width:100px;height:100px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#ffffff65,transparent 55%),var(--planet-color);box-shadow:inset -18px -10px 24px #27406130,0 14px 24px #7594b02a}.solar-planet-preview.saturn:after{content:'';position:absolute;width:155px;height:50px;border:9px solid #cab98f90;border-radius:50%;transform:rotate(-18deg)}.solar-planet-list{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:10px;margin:22px 0}.solar-planet-list button{display:flex;align-items:center;flex-direction:column;gap:9px;border:1px solid var(--border);border-radius:16px;padding:18px 5px;background:#fff;cursor:pointer;color:var(--ink)}.solar-planet-list button[aria-pressed=true]{border-color:#84abd4;background:#edf4fc}.solar-planet-list span{width:24px;height:24px;border-radius:50%;box-shadow:inset -5px -3px 7px #34536740}.solar-planet-list strong{font-size:12px;font-weight:600}.solar-planet-list small{font-size:10px;color:var(--muted)}.solar-context{margin-top:35px;padding:30px;border:1px solid var(--border);border-radius:22px;background:#fff}.solar-context h2{font-size:26px;letter-spacing:-.03em}.solar-context p{font-size:12px;line-height:2;color:var(--muted)}.solar-context a{color:#0066cc;text-decoration:underline}@media(max-width:850px){.solar-layout{grid-template-columns:1fr}.solar-stage{height:500px}.solar-information{display:grid;grid-template-columns:140px 1fr;column-gap:25px}.solar-planet-preview{grid-row:1/5}.solar-information small{grid-column:1/-1}.solar-planet-list{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:540px){.solar-stage{height:420px;border-radius:18px}.solar-toolbar{gap:12px}.solar-information{display:block}.solar-planet-preview{height:110px}.solar-information h2{font-size:28px}.solar-planet-list{gap:7px}.solar-planet-list button{padding:14px 5px}.solar-context{padding:20px}}
</style>
